BG_DK = {"css": "linear-gradient(115deg,#0B0C10 0%,#17181D 55%,#22242B 100%),repeating-linear-gradient(115deg,rgba(235,28,36,.05) 0 30px,rgba(0,0,0,0) 30px 90px)"}
