BAND_F = "contrast(1.2) saturate(1.1) brightness(.42)"
def BGI(k, f=BAND_F, pos="center 15%"): return dict(img=ph(k), pos=pos, f=f)
def BG_T(team): return BG_SS if team == "삼성" else BG_KT
def CARD(img, name, kicker, big=None, minor=None, team="KT", bg=None, **k): return S(0, "rf_card", img=ph(img), name=name, team=team, kicker=kicker, big=big, minor=minor or [], bg=bg or BG_T(team), noCenter=True, **k)
def BIGV(v, k, at, sub=None, size=None): return dict(dict(v=v, k=k, at=at), **({"sub": sub} if sub else {}), **({"size": size} if size else {}))
def MI(k, v, at): return dict(k=k, v=v, at=at)
def GOLD(img, name, en, profile, stats=None, team="KT", **k): return S(0, "rf_gold", img=ph(img), name=name, en=en, team=team, season="2026 SEASON", plist=profile, stats=stats or [], bg=BG_GOLD, noCenter=True, **k)
def BAND(who, vals, team=None, bg=None, **k): return S(0, "rf_band", who=who, team=team, vals=vals, bg=bg or (BG_T(team) if team else BG_DK), noCenter=True, **k)
def V(v, k, at, hi=False, size=None): return dict(dict(v=v, k=k, at=at, hi=hi), **({"size": size} if size else {}))
def DUO(title, cards, bg=None, **k): return S(0, "rf_duo", title=title, cards=cards, bg=bg or BG_DK, noCenter=True, **k)
def DC(img, name, at, stats=None, team="KT", focus=None): return dict(dict(img=ph(img), name=name, team=team, at=at, stats=stats or []), **({"focus": focus} if focus else {}))
def DS(k, v, at, hi=False): return dict(k=k, v=v, at=at, hi=hi)
def RBARS(title, items, mx, bg=None, glass=False, **k): return S(0, "rf_bars", title=title, items=items, max=mx, glass=glass, bg=bg or BG_DK, noCenter=True, **k)
def SP(img, name, bubbles, **k): return S(0, "speech", img=ph(img), name=name, bubbles=bubbles, **k)
def BB(date, text, at, hi=False): return dict(date=date, text=text, at=at, hi=hi)
def QQ(text, logos, **k): return S(0, "question", text=text, logos=logos, logoSize=k.pop('logoSize', 200), size=k.pop('size', 96), **k)

